"""Local PNG comparison viewer, review forms and clearly labeled preview derivatives."""
import copy,html,json,shutil,subprocess
from pathlib import Path
from PIL import Image,ImageDraw
ARMS=tuple(m+'_'+a for m in ('stationary','left','right') for a in ('closed','interact'))

def form(reviewer,identity):
    return dict(schema='worldline-factorial-video-human-review-v1',reviewer_slot=reviewer,reviewer_name='',identity=identity,
        review_status='unreviewed',independently_reviewed=False,all_arm_outcomes_unreviewed=True,
        arms={arm:dict(frames=[dict(index=i,generated_original_reviewed=False,target_original_reviewed=False,notes='') for i in range(17)],
            camera='unreviewed',door='unreviewed',first_open_frame=None,scene='unreviewed',notes='') for arm in ARMS},
        overall='unreviewed',notes='',rule='Both reviewers must inspect all17 original generated and target PNGs per arm; metrics never supply a verdict')

def contacts(out):
    tile=(156,88);band=22;result=[]
    all_image=Image.new('RGB',(17*tile[0],len(ARMS)*2*(tile[1]+band)),(244,244,240));all_draw=ImageDraw.Draw(all_image)
    for a,arm in enumerate(ARMS):
        image=Image.new('RGB',(17*tile[0],2*(tile[1]+band)),(244,244,240));draw=ImageDraw.Draw(image)
        for row,kind in enumerate(('generated','target')):
            for frame in range(17):
                with Image.open(out/'frames'/kind/arm/f'{frame:04d}.png') as original:thumb=original.convert('RGB').resize(tile,Image.Resampling.NEAREST)
                x=frame*tile[0];y=row*(tile[1]+band);image.paste(thumb,(x,y+band));draw.text((x+3,y+3),f'{kind} {frame:02d}',fill='black')
                top=(2*a+row)*(tile[1]+band);all_image.paste(thumb,(x,top+band));all_draw.text((x+3,top+3),f'{arm} {frame:02d}' if frame==0 else f'{kind} {frame:02d}',fill='black')
        path=out/'contacts'/f'{arm}.png';path.parent.mkdir(exist_ok=True);image.save(path);result.append(str(path.relative_to(out)))
    path=out/'contacts/all-six-arms.png';all_image.save(path);result.append(str(path.relative_to(out)));return result

def movies(out,enabled=True):
    executable=shutil.which('ffmpeg') if enabled else None
    if executable is None:return dict(status='not-created',reason='ffmpeg unavailable' if enabled else 'explicitly disabled',clips=[])
    version=subprocess.run([executable,'-version'],capture_output=True,text=True,timeout=10,check=True).stdout.splitlines()[0]
    folder=out/'clips';folder.mkdir();rows=[]
    for arm in ARMS:
        target=folder/(arm+'.mp4')
        args=[executable,'-hide_banner','-loglevel','error','-nostdin','-n','-framerate','25/3','-start_number','0','-i',str(out/'frames/generated'/arm/'%04d.png'),'-frames:v','17','-an','-c:v','libx264','-preset','veryfast','-crf','18','-pix_fmt','yuv420p','-movflags','+faststart','-map_metadata','-1',str(target)]
        try:
            subprocess.run(args,capture_output=True,text=True,timeout=60,check=True)
            rows.append(dict(arm=arm,status='created',path=str(target.relative_to(out))))
        except (subprocess.SubprocessError,OSError) as error:
            rows.append(dict(arm=arm,status='failed',error_type=type(error).__name__))
    return dict(status='completed' if all(r['status']=='created' for r in rows) else 'some-previews-failed',ffmpeg=version,
        presentation_fps=25/3,frames_per_clip=17,encoding='Lossy H264/YUV420 preview, CRF18; original PNGs remain exact',timing='Playback cadence is for inspection and does not measure generation speed',clips=rows)

def viewer(out,identity,summary):
    forms={str(i):form(i,identity) for i in (1,2)}
    for i,value in forms.items():(out/f'reviewer-{i}.json').write_text(json.dumps(value,indent=2)+'\n')
    data=json.dumps(dict(arms=ARMS,identity=identity,summary=summary,forms=forms,clips={a:'clips/'+a+'.mp4' for a in ARMS if (out/'clips'/(a+'.mp4')).is_file()}),allow_nan=False).replace('<','\\u003c')
    page=r'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Six-arm video review</title><style>
body{font:16px system-ui;margin:24px;background:#f6f5f1;color:#222}h1{font-size:25px}.controls{display:flex;gap:12px;flex-wrap:wrap;align-items:center;margin:14px 0}.pair{display:grid;grid-template-columns:1fr 1fr;gap:16px}.pair img{width:100%;background:#ddd}figure{margin:0}figcaption{font-weight:650;margin:8px 0}input[type=range]{width:330px}button,select,input,textarea{font:inherit;padding:7px}textarea{width:min(95%,700px);min-height:60px}fieldset{border:1px solid #bbb;margin-top:18px}label{margin-right:12px}.note{color:#555;max-width:1100px}pre{white-space:pre-wrap;font-size:13px}.criteria{background:#fff;padding:14px;border:1px solid #ddd}@media(max-width:750px){.pair{grid-template-columns:1fr}body{margin:12px}}
</style><h1>Six-arm generated-video comparison</h1><p class="note">The left images were generated by pretrained Wan2.2 with the trained block28 action adapter. The right images are programmed capture targets. Pixel scores do not decide whether camera or door controls succeeded. Click either image to inspect its exact original PNG at full size.</p>
<div class="controls"><label>Arm <select id="arm"></select></label><button id="play">Play</button><button id="previous">Previous</button><input id="frame" type="range" min="0" max="16" value="0"><button id="next">Next</button><strong id="position"></strong><a id="clip" hidden>MP4 preview for this arm</a></div>
<div class="pair"><figure><figcaption>Generated model output</figcaption><a id="genLink" target="_blank"><img id="gen" alt="Generated original frame"></a></figure><figure><figcaption>Programmed target capture</figcaption><a id="targetLink" target="_blank"><img id="target" alt="Programmed original target frame"></a></figure></div>
<p class="note">Synchronized playback shows the same frame index at 8⅓ frames/second for inspection. This is not a generation-speed measurement. Frame0 is a conditioned reconstruction and is excluded from future-frame averages.</p>
<div class="criteria"><strong>Frozen visible criteria</strong><p>Stationary: fixed viewpoint. Left: progressive coherent turn toward the window/plant side, door moves right. Right: progressive coherent turn toward the bench side, door moves left. Closed: door remains closed through frames1–16. Interact: doorway visibly opens at frame1 and remains coherently open through frame16. Smaller or later motion is partial; jitter, opposite motion, static motion when a turn was requested, ambiguous images or collapse do not demonstrate the required control.</p><p>Review all17 originals per arm and compare the targets. Exact angular motion is not inferred from generated pixels. One seen scene and one saved noise do not establish generalization. <a href="criteria.md">Read the complete original criteria</a>.</p></div>
<fieldset><legend>Independent manual review</legend><div class="controls"><label>Reviewer <select id="reviewer"><option value="1">Reviewer1</option><option value="2">Reviewer2</option></select></label><label>Name <input id="name"></label><button id="mark">Mark both originals at this frame reviewed</button><span id="count"></span></div><div class="controls"><label>Camera <select id="camera"></select></label><label>Door <select id="door"></select></label><label>First opening frame <input id="opening" type="number" min="0" max="16" placeholder="none"></label><label>Scene <select id="scene"></select></label></div><label>Frame notes<br><textarea id="frameNotes"></textarea></label><br><label>Arm notes<br><textarea id="armNotes"></textarea></label><div class="controls"><label><input id="independent" type="checkbox"> I reviewed independently</label><label>Overall <select id="overall"></select></label><button id="export">Download this review JSON</button></div><p class="note">No control verdict is prefilled. Reviewer forms stay separate. Downloads preserve per-frame review marks and disagreements; no automatic score threshold overrides a manual finding.</p></fieldset>
<details><summary>Per-arm pixel scores and baselines</summary><pre id="scores"></pre></details><p><a href="report.json">Full pixel report</a> · <a href="contacts/all-six-arms.png">All-frame thumbnail contact</a> · <a href="reviewer-1.json">Blank reviewer1 form</a> · <a href="reviewer-2.json">Blank reviewer2 form</a></p>
<script>const DATA=__DATA__;const $=id=>document.getElementById(id);const forms=DATA.forms;let timer=null,playing=false,displayRequest=0;const key='factorial-review-'+DATA.identity.plan_sha256;try{const saved=JSON.parse(localStorage.getItem(key));if(saved)for(const n of ['1','2'])if(saved[n]&&JSON.stringify(saved[n].identity)===JSON.stringify(DATA.identity))forms[n]=saved[n]}catch(e){}
for(const a of DATA.arms){const option=document.createElement('option');option.value=a;option.textContent=a.replaceAll('_',' ');$('arm').append(option)}
function options(id,values){for(const v of values){const x=document.createElement('option');x.value=v;x.textContent=v.replaceAll('_',' ');$(id).append(x)}}
options('camera',['unreviewed','achieved','partial','failed','not_demonstrated']);options('door',['unreviewed','achieved','partial','failed','not_demonstrated']);options('scene',['unreviewed','coherent','collapse','unclear']);options('overall',['unreviewed','all_six_achieved','some_controls_only','failed','not_demonstrated']);
function active(){return forms[$('reviewer').value]}function row(){return active().arms[$('arm').value]}function save(){try{localStorage.setItem(key,JSON.stringify(forms))}catch(e){}}
/*PAIR_BEGIN*/
function loadOriginal(src){return new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(src);image.onerror=()=>reject(new Error('Original frame unavailable'));image.src=src})}
async function showPair(arm,index){const request=++displayRequest,n=String(index).padStart(4,'0'),paths=['frames/generated/'+arm+'/'+n+'.png','frames/target/'+arm+'/'+n+'.png'];$('mark').disabled=true;$('position').textContent='Loading frame '+index+' /16';try{await Promise.all(paths.map(loadOriginal));if(request!==displayRequest)return false;$('gen').src=paths[0];$('genLink').href=paths[0];$('target').src=paths[1];$('targetLink').href=paths[1];$('position').textContent='Frame '+index+' /16';$('mark').disabled=false;return true}catch(e){if(request===displayRequest)$('position').textContent='Original frame unavailable';return false}}
/*PAIR_END*/
function draw(){const a=$('arm').value,i=+$('frame').value,loaded=showPair(a,i);const r=row(),f=active();$('name').value=f.reviewer_name;$('camera').value=r.camera;$('door').value=r.door;$('scene').value=r.scene;$('opening').value=r.first_open_frame??'';$('frameNotes').value=r.frames[i].notes;$('armNotes').value=r.notes;$('independent').checked=f.independently_reviewed;$('overall').value=f.overall;$('count').textContent=r.frames.filter(x=>x.generated_original_reviewed&&x.target_original_reviewed).length+' /17 marked in this arm';$('scores').textContent=JSON.stringify(DATA.summary[a],null,2);$('clip').hidden=!DATA.clips[a];if(DATA.clips[a])$('clip').href=DATA.clips[a];return loaded}
function stop(){playing=false;if(timer)clearTimeout(timer);timer=null;$('play').textContent='Play'}
async function advance(){if(!playing)return;$('frame').value=(+$('frame').value+1)%17;const loaded=await draw();if(playing&&loaded)timer=setTimeout(advance,120);else stop()}
$('play').onclick=()=>{if(playing)return stop();playing=true;$('play').textContent='Pause';draw().then(loaded=>{if(playing&&loaded)timer=setTimeout(advance,120);else stop()})};
$('previous').onclick=()=>{stop();$('frame').value=Math.max(0,+$('frame').value-1);draw()};$('next').onclick=()=>{stop();$('frame').value=Math.min(16,+$('frame').value+1);draw()};$('frame').oninput=()=>{stop();draw()};$('arm').onchange=()=>{stop();draw()};$('reviewer').onchange=()=>{stop();draw()};
$('mark').onclick=()=>{const r=row().frames[+$('frame').value];r.generated_original_reviewed=r.target_original_reviewed=true;save();draw()};
for(const id of ['camera','door','scene'])$(id).onchange=()=>{row()[id]=$(id).value;save()};$('opening').onchange=()=>{row().first_open_frame=$('opening').value===''?null:Math.max(0,Math.min(16,Math.trunc(+$('opening').value)));save()};$('name').oninput=()=>{active().reviewer_name=$('name').value;save()};$('frameNotes').oninput=()=>{row().frames[+$('frame').value].notes=$('frameNotes').value;save()};$('armNotes').oninput=()=>{row().notes=$('armNotes').value;save()};$('independent').onchange=()=>{active().independently_reviewed=$('independent').checked;save()};$('overall').onchange=()=>{active().overall=$('overall').value;save()};
$('export').onclick=()=>{const f=active();f.review_status=DATA.arms.every(a=>f.arms[a].frames.every(r=>r.generated_original_reviewed&&r.target_original_reviewed))?'all_frames_marked':'incomplete';f.all_arm_outcomes_unreviewed=DATA.arms.every(a=>f.arms[a].camera==='unreviewed'&&f.arms[a].door==='unreviewed');const url=URL.createObjectURL(new Blob([JSON.stringify(f,null,2)+'\n'],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='reviewer-'+f.reviewer_slot+'-completed.json';a.click();URL.revokeObjectURL(url);save()};draw();</script></html>'''
    (out/'index.html').write_text(page.replace('__DATA__',data))
